import { runInNewContext } from "node:vm";

function largestPowerOfTwoLessThan(n) {
  let k = 1;
  while (k * 2 < n) k *= 2;
  return k;
}
function refMerkleTreeHash(nodes) {
  if (nodes.length === 1) return nodes[0];
  const k = largestPowerOfTwoLessThan(nodes.length);
  return refNode(refMerkleTreeHash(nodes.slice(0, k)), refMerkleTreeHash(nodes.slice(k)));
}
function refAuditPath(nodes, index) {
  if (nodes.length === 1) return [];
  const k = largestPowerOfTwoLessThan(nodes.length);
  if (index < k)
    return [...refAuditPath(nodes.slice(0, k), index), refMerkleTreeHash(nodes.slice(k))];
  return [...refAuditPath(nodes.slice(k), index - k), refMerkleTreeHash(nodes.slice(0, k))];
}

const verifierSource = readFileSync(process.env.INCLUSION_VERIFY_MJS ?? "verify.mjs", "utf8");
