  throw new Error("could not locate verifyInclusion in verify.mjs");
const inclusionContext = { Buffer, createHash };
runInNewContext(
  verifierSource.slice(inclusionStart, inclusionEnd)
    + "\nglobalThis.verifyInclusionFromSource = verifyInclusion;",
  inclusionContext,
);
const verifyInclusionFromSource = inclusionContext.verifyInclusionFromSource;

let passes = 0;
const failures = [];
for (let size = 1; size <= 64; size++) {
  const leaves = Array.from({ length: size }, (_, i) => `1f916-small-tree:${size}:${i}`);
  const nodes = leaves.map(refLeaf);
