```cpp
// SPDX-License-Identifier: Apache-2.0
#include <algorithm>
#include <cstdint>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

#include "fold.h"

using lmcache::lmcache_native::Bitmap;
using lmcache::lmcache_native::fold;
using lmcache::lmcache_native::fold_grouped;
using lmcache::lmcache_native::unfold;
using lmcache::lmcache_native::unfold_grouped;

// Enumerate required cells directly from the documented interval contract.
// This oracle does not use the native implementation's consecutive-run logic.
bool required(size_t chunk, size_t length, int64_t window) {
  return chunk < length &&
         (window <= 0 || length - chunk <= static_cast<size_t>(window));
}

void check(size_t chunks, size_t ranks, const std::vector<int64_t>& windows,
           uint64_t presence) {
  const size_t groups = windows.size();
  Bitmap flat(chunks * groups * ranks);
  std::vector<Bitmap> rows(groups * ranks, Bitmap(chunks));
  std::vector<int64_t> row_windows;
  for (auto window : windows)
    for (size_t rank = 0; rank < ranks; ++rank)
      row_windows.push_back(window);
  for (size_t chunk = 0; chunk < chunks; ++chunk)
    for (size_t group = 0; group < groups; ++group)
      for (size_t rank = 0; rank < ranks; ++rank) {
        size_t cell = chunk * groups * ranks + group * ranks + rank;
        if ((presence >> cell) & 1) {
          flat.set(cell);
          rows[group * ranks + rank].set(chunk);
        }
      }
  auto fail = [&](const std::string& reason) {
    throw std::runtime_error(reason + " chunks=" + std::to_string(chunks) +
                             " ranks=" + std::to_string(ranks) +
                             " windows=" + std::to_string(windows[0]) + "," +
                             std::to_string(windows[1]) +
                             " presence=" + std::to_string(presence));
  };
  auto ranked = fold(flat, chunks, ranks, windows);
  auto grouped = fold_grouped(rows, row_windows);
  size_t best = 0;
  for (size_t length = 1; length <= chunks; ++length) {
    bool expected = true;
    for (size_t chunk = 0; chunk < length; ++chunk)
      for (size_t group = 0; group < groups; ++group)
        if (required(chunk, length, windows[group]))
          for (size_t rank = 0; rank < ranks; ++rank) {
            size_t cell = chunk * groups * ranks + group * ranks + rank;
            expected = expected && ((presence >> cell) & 1);
          }
    if (ranked.test(length - 1) != expected ||
        grouped.test(length - 1) != expected)
      fail("servable mask disagrees with required-cell oracle");
    if (expected) best = length;
  }
  if (ranked.size() != chunks || grouped.size() != chunks ||
      ranked.highest_set_bit() + 1 != static_cast<int64_t>(best) ||
      grouped.highest_set_bit() + 1 != static_cast<int64_t>(best))
    fail("size or longest hit differs");

  // Check every requested retain length, including one beyond the input size.
  for (size_t requested = 0; requested <= chunks + 1; ++requested) {
    const size_t length = std::min(requested, chunks);
    auto mask = unfold(requested, chunks, ranks, windows);
    auto masks = unfold_grouped(requested, chunks, row_windows);
    if (mask.size() != flat.size() || masks.size() != rows.size())
      fail("retain dimensions differ");
    for (size_t chunk = 0; chunk < chunks; ++chunk)
      for (size_t group = 0; group < groups; ++group)
        for (size_t rank = 0; rank < ranks; ++rank) {
          size_t cell = chunk * groups * ranks + group * ranks + rank;
          size_t row = group * ranks + rank;
          bool expected = required(chunk, length, windows[group]);
          if (masks[row].size() != chunks || mask.test(cell) != expected ||
              masks[row].test(chunk) != expected)
            fail("retain mask disagrees with interval contract");
          if (requested == best && expected && !flat.test(cell))
            fail("selected hit retains a missing shard");
        }
  }

  // The grouped contract does not assume any row ordering.
  std::reverse(rows.begin(), rows.end());
  std::reverse(row_windows.begin(), row_windows.end());
  if (fold_grouped(rows, row_windows).to_string() != grouped.to_string())
    fail("row permutation changed servable lengths");
}

int main() {
  uint64_t cases = 0;
  try {
    const std::vector<int64_t> windows{-1, 0, 1, 2, 3, 5};
    for (size_t chunks = 0; chunks <= 3; ++chunks)
      for (size_t ranks : {1u, 2u})
        for (int64_t first : windows)
          for (int64_t second : windows)
            for (uint64_t bits = 0; bits < (uint64_t{1} << (chunks * 2 * ranks));
                 ++bits) {
              check(chunks, ranks, {first, second}, bits);
              ++cases;
            }
    std::cout << "PASS " << cases << " exhaustive presence/window cases\n";
    std::cout << "Checked both layouts, all servable bits, longest hit, retain "
                 "masks, clamping, selected-hit availability and reversed rows.\n";
  } catch (const std::exception& error) {
    std::cerr << "FAIL after " << cases << " cases: " << error.what() << '\n';
    return 1;
  }
}

